<?php
require __DIR__.'/app/bootstrap.php';$user=require_permission('view_all_tickets');$staffStats=user_can('view_staff')?query("SELECT COUNT(*) total,COALESCE(SUM(employment_status='active'),0) active,COALESCE(SUM(employment_status='new'),0) new,COALESCE(SUM(employment_status='exited'),0) exited FROM staff_directory")->fetch():null;
[$ticketWhere,$ticketParams]=ticket_filter([],$user);$ticketStats=query("SELECT COUNT(*) total,COALESCE(SUM(status<>'closed'),0) open,COALESCE(SUM(status='closed'),0) closed,COALESCE(SUM(priority='urgent' AND status<>'closed'),0) urgent FROM tickets t".$ticketWhere,$ticketParams)->fetch();
$recent=query('SELECT t.id,t.ticket_number,t.subject,t.employee_name,t.status FROM tickets t'.$ticketWhere.' ORDER BY t.id DESC LIMIT 6',$ticketParams)->fetchAll();
page_start('Overview',$user);?><section class="hero-strip"><div><p class="eyebrow">A little clarity for your day</p><h2>Welcome, <?=e(explode(' ',$user['full_name'])[0])?>.</h2><p>Your people and requests, all in view.</p></div><div class="actions"><?php if(user_can('manage_staff')):?><a class="button button-secondary" href="employee-form.php">Add employee</a><?php endif;if(user_can('create_tickets')):?><a class="button" href="create-ticket.php">+ Create ticket</a><?php endif;?></div></section><div class="metrics"><?php if($staffStats):foreach(['total'=>['All employees','staff.php'],'active'=>['Active staff','staff.php?status=active'],'new'=>['New staff','staff.php?status=new'],'exited'=>['Exited staff','staff.php?status=exited']] as $key=>[$label,$url]):?><a class="metric" href="<?=$url?>"><span class="metric-label"><?=$label?></span><strong><?=(int)$staffStats[$key]?></strong><small>View directory →</small></a><?php endforeach;else:foreach(['total'=>'All tickets','open'=>'Open work','closed'=>'Closed tickets','urgent'=>'Urgent work'] as $key=>$label):?><div class="metric"><span class="metric-label"><?=$label?></span><strong><?=(int)$ticketStats[$key]?></strong></div><?php endforeach;endif;?></div><div class="split"><section class="panel flush"><div class="panel-heading"><h2>Recent tickets</h2><a href="index.php">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Request</th><th>Employee</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $ticket):?><tr><td><a href="ticket.php?id=<?=$ticket['id']?>"><?=e($ticket['subject'])?></a><span class="cell-secondary"><?=e($ticket['ticket_number'])?></span></td><td><?=e($ticket['employee_name'])?></td><td><span class="badge <?=e($ticket['status'])?>"><?=e(TICKET_STATUSES[$ticket['status']])?></span></td></tr><?php endforeach;if(!$recent):?><tr><td colspan="3" class="empty">No tickets yet. Create your first request.</td></tr><?php endif;?></tbody></table></div></section><section class="panel"><h2>Work at a glance</h2><p class="muted">Current ticket workload</p><?php foreach(['open'=>'Open work','closed'=>'Closed tickets','urgent'=>'Urgent & open'] as $key=>$label):?><div class="section-head"><span><?=$label?></span><strong><?=(int)$ticketStats[$key]?></strong></div><div class="report-bar"><span style="width:<?=round(100*(int)$ticketStats[$key]/max(1,(int)$ticketStats['total']))?>%"></span></div><?php endforeach;?><a href="index.php">Open ticket list →</a></section></div><?php if($staffStats):?><section class="panel"><div class="section-head"><h2>Latest staff updates</h2><a href="history.php">View history →</a></div><?php $updates=query('SELECT h.*,s.full_name,u.full_name actor_name FROM staff_history h JOIN staff_directory s ON s.id=h.staff_id JOIN users u ON u.id=h.actor_id ORDER BY h.id DESC LIMIT 5')->fetchAll();foreach($updates as $entry):?><article class="timeline-item"><h3><a href="employee.php?id=<?=$entry['staff_id']?>"><?=e($entry['full_name'])?></a> · <?=e(ucfirst($entry['event_type']))?></h3><small><?=e($entry['effective_date'])?> · <?=e($entry['actor_name'])?></small><p><?=e($entry['notes'])?></p></article><?php endforeach;if(!$updates):?><p class="muted">Staff updates will appear here as TLs record them.</p><?php endif;?></section><?php endif;page_end();
